@warp k -> escondite_2 spawn=down
# The grunt with the Hoist Key: talk to him: the fight; the win gives the key (a full bag: his beaten flag 812 stays, the key waits for the next talk; no second fight).
@script key_grunt npc
    npc_face_hero key_g
    jf lift_key_given said
    jf key_beaten give
    say hide.key.pre
    battle 88 0
    jv 0 1 won
    blackout
    end
  won:
    setf key_beaten
    say hide.key.win
  give:
    give_item llave_polea 1
    jv 0 0 full
    item_var 0 llave_polea
    say gl.gift
    setf lift_key_given
    say hide.key.after_give
    end
  full:
    say gl.found.full
    end
  said:
    say hide.key.after
@end
